const input = $json || {};

function clean(value, max = 2000) {
  return String(value ?? "").trim().slice(0, max);
}

const text = clean(input.message_text || input.text || input.message || "");
const telegramUserId = clean(input.user_id || input.telegram_user_id || input.from_user_id || "", 80);
const telegramChatId = clean(input.chat_id || input.telegram_chat_id || "", 80);
const rawMessage = (input.raw_update && input.raw_update.message) || {};
const messageId = clean(rawMessage.message_id || input.message_id || "", 80);
const providerDate = Number(rawMessage.date || input.provider_timestamp || input.timestamp || 0);
const userName = clean(input.user_name || input.telegram_user_name || "", 120);
const errors = [];

if (!text) errors.push("message_text is required");
if (!telegramUserId) errors.push("user_id is required");
if (!telegramChatId) errors.push("chat_id is required");
if (!messageId) errors.push("message_id is required");
if (!Number.isInteger(providerDate) || providerDate <= 0) errors.push("provider timestamp is required");

if (errors.length > 0) {
  return [{
    json: {
      success: false,
      send_allowed: false,
      status: "invalid_relay_input",
      errors,
      sends_telegram: false,
      can_trigger_outbound_llm: false,
      writes: false,
      records_audit_trace: false,
    },
  }];
}

return [{
  json: {
    success: true,
    status: "normalized",
    text,
    telegram_user_id: telegramUserId,
    telegram_chat_id: telegramChatId,
    message_id: messageId,
    user_name: userName,
    gateway_payload: {
      message: {
        message_id: Number.isSafeInteger(Number(messageId)) ? Number(messageId) : messageId,
        date: providerDate,
        text,
        from: { id: telegramUserId },
        chat: { id: telegramChatId, type: "private" },
      },
    },
  },
}];

const item = $json || {};
if (item.success !== true) return [{ json: item }];

function parseBaseUrl(value) {
  const label = "[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?";
  const match = String(value ?? "").match(
    new RegExp(`^(https?):\\/\\/(\\[::1\\]|${label}(?:\\.${label})*)(?::([0-9]{1,5}))?$`, "i"),
  );
  if (!match) return null;
  const port = match[3] ? Number(match[3]) : null;
  if (port !== null && (port < 1 || port > 65535)) return null;
  return {
    protocol: `${match[1].toLowerCase()}:`,
    hostname: match[2].toLowerCase(),
    port,
  };
}

const APPROVED_HTTPS_ORIGIN = "https://amadeus-pig-tracking-system.onrender.com";

function baseUrlIsLocalOrTls(value) {
  const parsed = parseBaseUrl(value);
  if (!parsed) return false;
  if (parsed.protocol === "https:") return value === APPROVED_HTTPS_ORIGIN;
  if (parsed.protocol !== "http:") return false;
  return new Set(["127.0.0.1", "localhost", "[::1]"]).has(parsed.hostname);
}

function cleanVariable(value) {
  let text = String(value ?? "").replace(/[\u200B-\u200D\uFEFF]/g, "").trim();
  const first = text[0];
  const last = text[text.length - 1];
  if ((first === "\"" && last === "\"") || (first === "'" && last === "'") || (first === "`" && last === "`")) {
    text = text.slice(1, -1).trim();
  }
  return text;
}

function workflowVariable(name) {
  try {
    if (typeof $vars !== "undefined" && $vars && $vars[name] !== undefined) {
      return cleanVariable($vars[name]);
    }
  } catch (error) {
    return "";
  }
  return "";
}

function normalizeBaseUrl(value) {
  return cleanVariable(value);
}

function baseUrlDiagnostic(value) {
  const parsed = parseBaseUrl(value);
  return {
    configured: value.length > 0,
    starts_with_http: /^https?:\/\//i.test(value),
    parsed_protocol: parsed ? parsed.protocol : "invalid",
    parsed_hostname: parsed ? parsed.hostname : "invalid",
    length: value.length,
  };
}

const baseUrl = normalizeBaseUrl(workflowVariable("OOM_SAKKIE_GATEWAY_BASE_URL"));
const tokenLength = workflowVariable("OOM_SAKKIE_TELEGRAM_GATEWAY_TOKEN").length;
const errors = [];

if (!baseUrl) errors.push("n8n variable OOM_SAKKIE_GATEWAY_BASE_URL is required");
if (baseUrl && !baseUrlIsLocalOrTls(baseUrl)) errors.push("OOM_SAKKIE_GATEWAY_BASE_URL must use https, or local http on localhost/127.0.0.1/::1");
if (tokenLength < 32) errors.push("n8n variable OOM_SAKKIE_TELEGRAM_GATEWAY_TOKEN must be at least 32 characters");

if (errors.length > 0) {
  return [{
    json: {
      ...item,
      success: false,
      send_allowed: false,
      status: "relay_env_not_ready",
      errors,
      base_url_diagnostic: baseUrlDiagnostic(baseUrl),
      sends_telegram: false,
      can_trigger_outbound_llm: false,
      writes: false,
      records_audit_trace: false,
    },
  }];
}

return [{
  json: {
    ...item,
    gateway_url: `${baseUrl}/api/oom-sakkie/channels/telegram/message`,
  },
}];
